"""Original Sjogren disease questions for the Sjogren/IgG4 chapter."""
from qbank_authoring import question,ref
rows=[]
C=ref('ACR/EULAR 2016 Sjogren classification criteria','https://ard.bmj.com/content/76/1/9')
B=ref('BSR Sjogren disease management guideline: 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC12013823/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A woman has persistent gritty eyes, dry mouth requiring water to swallow dry food, recurrent dental caries and anti-Ro/SSA positivity. Which diagnosis is most likely?', 'Sjogren disease',[
 ('Primary systemic sclerosis','Skin sclerosis, Raynaud and a fibrosing vascular phenotype would be more characteristic.'),('Primary antiphospholipid syndrome','A thrombotic or obstetric phenotype is not described.'),('Adult-onset Still disease','The expected fever/rash/neutrophilic inflammatory pattern is absent.')],
 'Recognize autoimmune exocrine dysfunction','**Ocular and oral dryness with a supporting autoimmune phenotype suggests Sjogren disease.**',['Dryness has many nonautoimmune causes, so medication and exposure review remain essential.','Sjogren can be systemic rather than confined to glands.'], '**Confirm objective dysfunction and assess organ involvement.**',['Use appropriate ocular and salivary tests.','Ask about swelling, purpura, neuropathy, breathlessness and renal symptoms.'],[['Sicca','Common glandular phenotype'],['Anti-SSA','Important supporting antibody'],['Systemic assessment','Required when clinical clues are present']],[C,B],style='clinical_scenario')

q('An eligible patient has anti-SSA positivity and a Schirmer result of 3 mm in 5 minutes. What total do these findings contribute to the 2016 Sjogren classification score?', '4 points',[
 ('2 points','Anti-SSA alone contributes three, not one.'),('3 points','This omits the abnormal Schirmer point.'),('6 points','The Schirmer test is worth one point, not three.')],
 'Use the weighted objective criteria','**Anti-SSA supplies three points and Schirmer at most five millimeters in five minutes supplies one.**',['A total of at least four can meet classification in an eligible patient without exclusions.','The framework also includes labial biopsy, ocular staining and unstimulated salivary flow.'], '**Distinguish classification from a clinical diagnosis based on the full context.**',['Medication effects and other exclusion conditions matter.','Symptoms alone do not supply the same objective test points.'],[['Anti-SSA','3'],['Abnormal Schirmer','1'],['Total','4']],[C],style='clinical_scenario')

q('Which antibody finding alone was removed from the 2016 Sjogren classification scoring because it did not provide adequate independent discrimination?', 'Isolated anti-La/SSB positivity without anti-SSA',[
 ('Anti-SSA positivity','This remains a high-weight criterion.'),('Focal lymphocytic sialadenitis on biopsy','This is a histological finding rather than an antibody and remains highly weighted.'),('An abnormal ocular staining score','This is an objective ocular measure, not the removed antibody item.')],
 'Do not give isolated SSB the same weight as SSA','**Isolated anti-SSB without anti-SSA does not earn the antibody score in the 2016 framework.**',['A patient can still need a clinical evaluation for sicca and systemic disease.','Laboratory assay reliability and the full phenotype remain important.'], '**Use objective testing to clarify uncertainty.**',['Do not diagnose or exclude disease from a small antibody panel alone.','Consider biopsy when the result would meaningfully change assessment.'],[['Anti-SSA','Scored'],['Isolated anti-SSB','Not scored independently'],['Objective gland tests','Help define the phenotype']],[C])

q('A patient has persistent objective sicca but negative anti-SSA. Which investigation can provide important diagnostic evidence if clinical suspicion remains?', 'Minor labial salivary gland biopsy with expert histological assessment',[
 ('Repeated ANA titers alone','ANA alone does not establish focal lymphocytic sialadenitis or gland dysfunction.'),('Serum urate alone','This does not investigate the suspected autoimmune glandular process.'),('A normal chest radiograph as definitive exclusion','This cannot exclude Sjogren disease.')],
 'Seronegativity does not end the evaluation','**A labial biopsy can demonstrate focal lymphocytic sialadenitis in selected seronegative patients.**',['A focus score of at least one per four square millimeters is the classification threshold.','Sampling quality and expert interpretation affect usefulness.'], '**Discuss whether the result will change diagnosis or management.**',['Salivary ultrasound can add supportive information but is not itself a scored 2016 item.','Consider nonautoimmune causes and exclusion conditions.'],[['Anti-SSA negative','Disease still possible'],['Labial biopsy','Can add high-weight evidence'],['Interpretation','Needs adequate tissue and expertise']],[C,B],style='clinical_scenario')

q('A 74-year-old develops dry mouth soon after starting oxybutynin and a tricyclic antidepressant. There is no gland swelling or systemic autoimmune phenotype. Which explanation should be assessed first?', 'Medication-associated anticholinergic sicca',[
 ('Sjogren disease established from dry mouth alone','Symptoms alone are insufficient, especially with a strong alternative exposure.'),('IgG4-related disease established without swelling, imaging or tissue','The described drug timing provides a more immediate explanation.'),('Sarcoidosis established despite no supporting systemic evidence','It remains a differential in selected settings but is not established here.')],
 'Review common reversible causes before labeling autoimmune disease','**Anticholinergic medicines commonly reduce salivary secretion.**',['Age, dehydration, diabetes and other exposures can also contribute.','Multiple causes can coexist.'], '**Review the medication list and objective findings.**',['Discuss alternatives with the prescriber rather than stopping necessary medication unsupervised.','Persistent symptoms or systemic clues justify further autoimmune evaluation.'],[['Anticholinergic exposure','Common sicca cause'],['Objective testing','Defines dysfunction'],['Autoimmune diagnosis','Requires supporting context']],[B],style='clinical_scenario')

q('A woman with Sjogren disease has hypokalemic weakness, normal-anion-gap metabolic acidosis and urine pH 6.3 despite systemic acidosis. Which renal complication is most likely?', 'Distal renal tubular acidosis from tubulointerstitial involvement',[
 ('Proximal RTA as established solely by urine pH above 5.5 during sustained acidosis','In established bicarbonate depletion, proximal RTA can acidify urine; this pattern favors distal acidification failure.'),('Type 4 RTA','This generally causes hyperkalemia rather than the stated hypokalemia.'),('Pure gastrointestinal bicarbonate loss','Diarrhea is a differential, but an inappropriately alkaline urine in this context supports a renal acidification defect.')],
 'Sjogren renal disease is often tubulointerstitial','**Distal RTA causes impaired urinary acidification and can produce marked potassium depletion.**',['Nephrocalcinosis or stones may coexist.','Assess medications and other causes of normal-gap acidosis.'], '**Correct potassium and acid-base deficits safely and evaluate renal inflammation.**',['Severe hypokalemia can cause arrhythmia and paralysis.','Alkali replacement and immune treatment decisions address different aspects of the problem.'],[['Distal RTA','Inappropriately high urine pH during acidosis'],['Type 4 RTA','Usually hyperkalemic'],['Immediate risk','Potassium-related cardiac/neuromuscular effects']],[B],style='clinical_scenario')

q('A patient with Sjogren disease develops persistent unilateral parotid enlargement, palpable nodes and low C4. What is the most important next concern?', 'B-cell lymphoma requiring targeted evaluation and tissue diagnosis',[
 ('An uncomplicated sicca symptom requiring only more water','Persistent gland asymmetry and nodes are warning findings.'),('A transient medication-induced dry mouth as the complete explanation','This does not explain the mass-like and systemic features.'),('A benign salivary stone as certain without imaging or evaluation','Obstruction is a differential, but lymphoma must be considered in this risk setting.')],
 'Recognize the lymphoproliferative warning phenotype','**Persistent salivary swelling, lymphadenopathy, low complement and other B-cell activation features can signal increased lymphoma risk.**',['MALT lymphoma is an important associated type.','Not all gland swelling is lymphoma, so diagnosis requires appropriate assessment.'], '**Investigate new persistent swelling promptly.**',['Use imaging and the most informative tissue sampling strategy.','Review weight loss, fever, night sweats, cryoglobulins and monoclonal proteins as appropriate.'],[['Persistent gland swelling','Warning feature'],['Low C4/nodes','Additional risk context'],['Tissue','Establishes the diagnosis']],[B],style='clinical_scenario')

q('Sjogren disease with palpable purpura, low complement, neuropathy and circulating cryoglobulins most strongly suggests which complication?', 'Cryoglobulinemic small-vessel vasculitis',[
 ('Simple xerosis','Dry skin does not explain the systemic vasculitic pattern.'),('Primary osteoarthritis','This does not cause purpura, complement consumption or neuropathy.'),('Isolated carpal tunnel syndrome','An entrapment neuropathy alone does not explain the full systemic presentation.')],
 'Link B-cell activation to vascular organ injury','**Cryoglobulinemia can produce cutaneous, neurological and renal disease.**',['Evaluate hepatitis C and other alternative or contributing causes.','Monoclonal components and lymphoma risk may need investigation.'], '**Assess organ threat before choosing therapy.**',['Skin biopsy or other targeted tissue can support the mechanism.','Severe disease may require systemic immune treatment beyond sicca care.'],[['Purpura','Small-vessel injury'],['Neuropathy/renal disease','Potential systemic involvement'],['Cryoglobulins','Require correct specimen handling and context']],[B])

q('A patient with Sjogren disease has progressive sensory ataxia, loss of joint-position sense and relatively preserved strength. Which neurological phenotype deserves consideration?', 'Sensory neuronopathy/ganglionopathy',[
 ('Pure myopathy','This does not primarily cause marked proprioceptive loss.'),('Myasthenia gravis','This produces fatigable motor weakness without the same sensory loss.'),('Isolated essential tremor','This does not explain objective large-fiber sensory dysfunction.')],
 'Not every Sjogren neuropathy is a distal length-dependent polyneuropathy','**Sensory ganglionopathy can produce non-length-dependent sensory loss and ataxia.**',['Other neuropathies, including small-fiber and vasculitic forms, also occur.','Exclude nutritional, toxic, paraneoplastic and other causes.'], '**Use neurological examination and electrophysiology to define the pattern.**',['Large-fiber studies can be normal in isolated small-fiber disease.','Treatment depends on mechanism, severity and chronic damage.'],[['Ganglionopathy','Proprioceptive loss/ataxia'],['Small-fiber neuropathy','Pain/autonomic symptoms'],['Vasculitic neuropathy','Often painful asymmetric deficits']],[B],style='clinical_scenario')

q('A patient with Sjogren disease has dry cough, crackles and a reduced DLCO. Which complication should be assessed?', 'Interstitial lung disease',[
 ('Oral candidiasis as the sole explanation','This does not explain crackles and gas-transfer impairment.'),('Uncomplicated dental caries','Dental disease does not cause the stated pulmonary physiology.'),('Distal RTA as the only possible cause of chronic lung findings','Acid-base disease can affect breathing but does not explain the complete parenchymal pattern.')],
 'Assess pulmonary disease beyond upper-airway dryness','**Sjogren can cause ILD and airway disease.**',['HRCT and pulmonary function testing define the pattern and burden.','Cysts, nodules or focal lesions may require a broader differential, including lymphoproliferative disease.'], '**Coordinate pulmonary and rheumatological assessment.**',['Rule out infection and other causes when indicated.','Treatment depends on severity, progression and the specific pulmonary phenotype.'],[['Dry airway symptoms','Can occur without ILD'],['Crackles/DLCO change','Investigate lung involvement'],['Focal/cystic lesions','Require pattern-specific evaluation']],[B,ref('ERS/EULAR CTD-ILD guideline','https://publications.ersnet.org/content/erj/67/1/2402533')],style='clinical_scenario')

q('Which preventive intervention is particularly important for chronic Sjogren-related xerostomia?', 'Regular dental care and fluoride-based caries prevention',[
 ('Avoiding all tooth brushing because mucosa is dry','This increases preventable dental disease.'),('Long-term systemic glucocorticoids solely to prevent caries','These do not substitute for oral preventive care and add harm.'),('Routine antibiotics indefinitely in every asymptomatic patient','This is not an appropriate universal caries-prevention strategy.')],
 'Protect teeth when salivary defenses are reduced','**Reduced saliva increases caries, candidiasis and oral discomfort risk.**',['Use dental review, fluoride and individualized saliva-preserving measures.','Review sugar exposure and medications that worsen dryness.'], '**Treat symptoms and prevent avoidable damage.**',['Saliva substitutes and sugar-free stimulation can help selected patients.','Persistent oral soreness warrants examination for infection or other lesions.'],[['Fluoride/dental review','Caries prevention'],['Saliva support','Symptom care'],['Mucosal lesions','Examine rather than assume dryness alone']],[B])

q('Which agent may improve Sjogren sicca symptoms by stimulating residual glandular secretion when suitable?', 'Pilocarpine',[
 ('Oxybutynin','Its anticholinergic effects can worsen dryness.'),('Amitriptyline','Its anticholinergic burden can worsen sicca.'),('Diphenhydramine','This can also reduce secretion and worsen dryness.')],
 'A secretagogue needs residual function and a safety review','**Pilocarpine is a muscarinic agonist that can improve salivary and other sicca symptoms.**',['Sweating, flushing and gastrointestinal effects can limit tolerance.','Assess relevant cardiopulmonary and ocular contraindications before use.'], '**Titrate according to response and adverse effects.**',['It does not replace topical eye care or dental prevention.','A lack of residual glandular function can limit benefit.'],[['Pilocarpine','Secretagogue'],['Anticholinergics','Often worsen dryness'],['Response','Depends partly on residual function']],[B])

q('Which statement about hydroxychloroquine in Sjogren disease is most accurate?', 'It may be considered for selected systemic or articular symptoms, but is not a reliably effective stand-alone treatment for glandular dryness',[
 ('It restores normal gland function in nearly every patient','Clinical trial evidence does not support this universal claim.'),('It replaces all topical ocular and oral care','Local symptom and preventive care remain important.'),('It is an established treatment for every severe organ manifestation as monotherapy','Organ-threatening disease often needs a different systemic strategy.')],
 'Match the drug to the symptom domain','**Sicca, fatigue, arthritis and organ disease are distinct treatment targets.**',['Hydroxychloroquine has a selected role rather than a guaranteed effect on dryness.','Review retinal safety and the actual indication before long-term use.'], '**Measure the outcome for which it was prescribed.**',['Continue appropriate ocular and oral measures.','Avoid escalating systemic immunosuppression for dryness alone without an evidence-based target.'],[['Sicca','Primarily local/supportive strategies'],['Selected joint/systemic symptoms','HCQ may be considered'],['Severe organ disease','Organ-specific systemic treatment']],[B,ref('JOQUER randomized hydroxychloroquine trial','https://doi.org/10.1001/jama.2014.7682')])

q('A patient with Sjogren disease has rapidly progressive glomerulonephritis and biopsy-supported cryoglobulinemic vasculitis. Which principle is appropriate?', 'Use organ-threatening disease-directed systemic treatment rather than sicca measures alone',[
 ('Use artificial tears as the sole treatment for the renal syndrome','Local dryness care does not treat glomerular vasculitis.'),('Wait until anti-SSA becomes negative before treating organ injury','Antibody negativity is not a prerequisite for urgent care.'),('Treat every patient with isolated dry mouth using the same aggressive regimen','The benefit-risk balance differs greatly in gland-limited disease.')],
 'Severity and mechanism determine systemic treatment','**Renal or severe neurological/vasculitic disease can justify potent immunomodulation.**',['Regimens are selected by the organ and can include glucocorticoids with other agents, including selected B-cell-directed treatment.','Exclude infection and lymphoproliferative or viral drivers.'], '**Coordinate timely specialist management.**',['Monitor organ response and treatment toxicity.','Retain appropriate sicca care while treating the systemic disease.'],[['Gland-limited symptoms','Local/supportive care'],['Organ threat','Systemic therapy'],['Driver assessment','Infection, cryoglobulins and B-cell disease']],[B],style='clinical_scenario')

if __name__=='__main__':print(f'Sjogren/IgG4 draft: {len(rows)} questions')
